proof.tex:
\begin{proof}
Theorem~\ref{fnd:generalrelativeinterioropen} proves ordinary openness for arbitrary analytic spaces, and \mbox{\hyperref[fnd:nag001810:admissible-cover]{The boundary identity}} gives locality on admissible analytic-domain covers of the base. Proposition~\ref{fnd:generaldomainordinaryinterior} identifies the relative interior of every analytic-domain inclusion with its ordinary topological interior. Theorem~\ref{fnd:affinoidboundarylessfinite} proves the affinoid finite criterion, including the canonical finite-module topology and hence admissibility over trivially valued fields. Finally, Proposition~\ref{fnd:generalizedfinitebasechange} identifies a finite affinoid base change with its finite tensor algebra equipped with that topology. Applying this on affinoid charts of an arbitrary base change and using the analytic-domain gluing theorem proves stability of finite morphisms.
\end{proof}

statement.tex:
\begin{theorem}\label{fnd:boundaryfacts}
Relative interior is open and behaves locally on the base under analytic-domain covers. If $V\subset X$ is an analytic domain, $\operatorname{Int}(V/X)$ equals its ordinary topological interior in $X$. An affinoid morphism $\mathcal M(B)\to\mathcal M(A)$ is boundaryless if and only if $A\to B$ is finite and admissible. Finite morphisms are stable under base change.
\end{theorem}

\begin{proposition}\label{fnd:formalmetricwell}
These prescriptions define a continuous metric on $L$, independent of the formal frames. They commute with pullback of formal line bundles and remain unchanged when the model and line bundle are pulled back along an admissible formal blow-up.
\end{proposition}

\begin{theorem}[Reduction of strict analytic germs]\label{fnd:germtheorem}
For strictly analytic spaces, germ reduction is functorial and independent of the model and neighborhood. Germ subdomains correspond to birational subspaces, compatibly with inclusions, intersections and finite unions. A germ is good precisely when its reduction is affine in the birational category. A morphism is separated at a point precisely when the corresponding reduction morphism is separated; the point lies in relative interior precisely when that reduction morphism is proper.
\end{theorem}

\begin{theorem}\label{fnd:quasismooth}
A morphism $f:Y\to X$ is quasi-smooth at $y$ if and only if it is analytically flat there and its $\mathcal H(f(y))$-analytic fibre is geometrically regular at $y$. For morphisms between good spaces, it is smooth at $y$ if and only if it is quasi-smooth and boundaryless there. Analytic-domain inclusions are flat. For a morphism between good spaces, naive flatness of a coherent sheaf at an interior point implies analytic flatness there.
\end{theorem}

\begin{theorem}[Ordinary regularity of quasi-smooth morphisms]
\label{fnd:quasismoothordinaryregular}
Let $f:Y\to X$ be a morphism of good analytic spaces over any complete non-Archimedean field, quasi-smooth at $y$, and put $x=f(y)$. Then $\mathcal O_{X,x}\to\mathcal O_{Y,y}$ is a regular homomorphism of Noetherian local rings. If $X=\mathcal M(A)$ and $Y=\mathcal M(B)$ are affinoid, then $A_{\ker(x)}\to B_{\ker(y)}$ is regular as well.
\end{theorem}

\begin{corollary}[Normality and regularity along quasi-smooth maps]
\label{fnd:quasismoothnormalascent}
Under the hypotheses of the preceding theorem, $\mathcal O_{Y,y}$ is normal if and only if $\mathcal O_{X,x}$ is normal, and it is regular if and only if $\mathcal O_{X,x}$ is regular. In particular a quasi-smooth good space over a normal good analytic space is normal. These assertions hold after every analytic base change and complete extension for which the spaces are good.
\end{corollary}

proof.tex:
\begin{proof}
\begingroup\makeatletter
\def\@currentHref{foundations.nag-001808.interior-to-proper}
\def\@currentlabel{}
\def\@currentlabelname{Interior gives proper reduction}
\Hy@raisedlink{\hyper@anchorstart{\@currentHref}\hyper@anchorend}
\label{fnd:nag001808:interior-to-proper}
\makeatother\endgroup
Suppose first that $y$ is interior. Choose finitely many affinoid domains $X_i\subset X$, all containing $x$, whose union is a neighborhood of $x$. Write $Y_i=f^{-1}(X_i)$. By Definition~\ref{fnd:alltargetrelativeinterior}, each $Y_i$ has an affinoid neighborhood $V_i$ of $y$ with $y\in\operatorname{Int}(V_i/X_i)$. Proposition~\ref{fnd:goodgermproperinterior} says that the reduction of $(V_i,y)\to(X_i,x)$ is proper. Since $V_i$ is an ordinary neighborhood in $Y_i$, it represents the same germ. Theorem~\ref{fnd:allgradedgermreduction} identifies these morphisms with the restrictions of the original reduction over the open cover $\mathscr R(X_i,x)$ of $\mathscr R(X,x)$. Target locality in Corollary~\ref{fnd:propergermreductionbasechange} proves properness.

\begingroup\makeatletter
\def\@currentHref{foundations.nag-001808.proper-to-interior}
\def\@currentlabel{}
\def\@currentlabelname{Proper reduction gives relative interior}
\Hy@raisedlink{\hyper@anchorstart{\@currentHref}\hyper@anchorend}
\label{fnd:nag001808:proper-to-interior}
\makeatother\endgroup
Conversely, suppose the reduction is proper and let $U\subset X$ be any affinoid domain containing $x$. Put $V=f^{-1}(U)$. The inverse-image formula for germ reductions and Corollary~\ref{fnd:propergermreductionbasechange} show that $\mathscr R(V,y)\to\mathscr R(U,x)$ is proper. The latter target is affine. By the definition of properness for birational spaces, its source is the pullback of that affine object to $\widetilde{\mathcal H(y)}^{\rm gr}$, hence is affine. \mbox{\hyperref[fnd:nag001982:affine-to-good]{The affine-to-good clause}} therefore makes $(V,y)$ a good germ. Choose an affinoid neighborhood $W$ of $y$ in $V$. Its reduction agrees with that of $V$, so Proposition~\ref{fnd:goodgermproperinterior} gives $y\in\operatorname{Int}(W/U)$. This is the witness required for the arbitrary target domain $U$.
\end{proof}

\begin{proof}
Fix an interior point $y$ and write $x=f(y)$. Work inside Hausdorff open neighborhoods of $x$ and $y$; these do not alter their germs or the \mbox{\hyperref[fnd:nag001808:proper-to-interior]{proper-to-interior implication}}. Choose finitely many affinoid domains $X_i$ containing $x$ whose union contains an open neighborhood $N$ of $x$. By \hyperref[fnd:alltargetrelativeinterior]{the all-target-domain definition}, for $Y_i=f^{-1}(X_i)$ choose affinoid neighborhoods $V_i$ of $y$ in $Y_i$ such that $y\in\operatorname{Int}(V_i/X_i)$. Affinoid interior is open. Consequently there is an open neighborhood $Z_i$ of $y$ in $Y_i$, contained in $V_i$, on which the reduction of $(Y_i,z)\to(X_i,f(z))$ is proper for every $z\in Z_i$. Here we first restrict to the ordinary interior of $V_i$ in $Y_i$, so the two source germs agree.

For each $i$, choose an ordinary open neighborhood $O_i$ of $y$ in $Y$ with $O_i\cap Y_i\subset Z_i$, and put $O=f^{-1}(N)\cap\bigcap_iO_i$. This is an open neighborhood of $y$. For $z\in O$, put $x'=f(z)$. The members $X_i$ containing $x'$ cover the germ $(X,x')$: the other finitely many compact domains are closed in the chosen Hausdorff neighborhood and can be removed near $x'$, while $N\subset\bigcup_iX_i$. For every remaining member, $z\in Z_i$, so the reduced morphism over $\mathscr R(X_i,x')$ is proper. Target locality proves properness of $\mathscr R(Y,z)\to\mathscr R(X,x')$. The \mbox{\hyperref[fnd:nag001808:proper-to-interior]{proper-to-interior implication}} yields $z\in\operatorname{Int}(Y/X)$. Thus $O$ is contained in the relative interior.
\end{proof}

statement.tex:
\begin{theorem}[Openness of relative interior]
\label{fnd:generalrelativeinterioropen}
For every morphism of analytic spaces, $\operatorname{Int}(Y/X)$ is open in the ordinary topology of $Y$.
\end{theorem}

proof.tex:
\begin{proof}
At each $x\in X$, admissibility supplies a finite subdomain-germ covering subordinate to the given family. Theorem~\ref{fnd:allgradedgermreduction} turns it into an open covering of $\mathscr R(X,x)$ and identifies the reductions of the inverse-image germs with the corresponding inverse images. A reduction morphism is proper if and only if all these restrictions are proper, by Corollary~\ref{fnd:propergermreductionbasechange}. The \mbox{\hyperref[fnd:nag001808:interior-to-proper]{forward}} and \mbox{\hyperref[fnd:nag001808:proper-to-interior]{reverse}} implications give the boundary identity. After \mbox{\hyperref[fnd:nag001808:interior-to-proper]{interior implies properness}}, the same corollary preserves properness under analytic base change over $L$. The \mbox{\hyperref[fnd:nag001808:proper-to-interior]{reverse implication}} on $Y'$ proves the second assertion.
\end{proof}

statement.tex:
\begin{theorem}[Domain locality and analytic base change]
\label{fnd:generalboundarybasechangeglocal}
\begingroup\makeatletter
\def\@currentHref{foundations.nag-001810.admissible-cover}
\def\@currentlabel{}
\def\@currentlabelname{Boundary identity on admissible covers}
\Hy@raisedlink{\hyper@anchorstart{\@currentHref}\hyper@anchorend}
\label{fnd:nag001810:admissible-cover}
\makeatother\endgroup
Let $(X_i)$ be an admissible analytic-domain covering of $X$ and put $Y_i=f^{-1}(X_i)$. Then
\[
 \partial(Y/X)=\bigcup_i\partial(Y_i/X_i).
\]
\begingroup\makeatletter
\def\@currentHref{foundations.nag-001810.analytic-base-change}
\def\@currentlabel{}
\def\@currentlabelname{Interiority under analytic base change}
\Hy@raisedlink{\hyper@anchorstart{\@currentHref}\hyper@anchorend}
\label{fnd:nag001810:analytic-base-change}
\makeatother\endgroup
If $X'\to X$ is an analytic morphism over any complete valued extension $L/K$, $Y'=Y\times_X X'$, and $y'\in Y'$ maps to $y\in Y$, then
\[
 y\in\operatorname{Int}(Y/X)
       \quad\Longrightarrow\quad
 y'\in\operatorname{Int}(Y'/X').
\]
\end{theorem}

\begin{corollary}[The universal good-space test]
\label{fnd:universalboundarylesstest}
A morphism $f:Y\to X$ is boundaryless if and only if, for every complete valued extension $L/K$ and every morphism $X'\to X$ from a good $L$-analytic space, the space $Y'=Y\times_X X'$ is good and the induced good-space morphism $Y'\to X'$ is boundaryless.
\end{corollary}

\begin{theorem}[Inner flatness with nontrivially valued completed residue field]
\label{fnd:nontrivialinnercoherentflatness}
Let $f:Y\to X$ be a morphism of good analytic spaces over any complete field and let $\mathcal F$ be coherent on $Y_G$. At an inner point $y$, with $\mathcal H(f(y))$ nontrivially valued, naive $X$-flatness of $\mathcal F$ is equivalent to analytic $X$-flatness.
\end{theorem}

\begin{theorem}[Naive and analytic flatness at every inner point]
\label{fnd:generalinnercoherentflatness}
Let $K$ be any complete non-Archimedean field, let $f:Y\to X$ be a morphism of good $K$-analytic spaces, and let $\mathcal F$ be coherent on $Y_G$. For every $y\in\operatorname{Int}(Y/X)$, the following are equivalent: $\mathcal F_y$ is flat over $\mathcal O_{X,f(y)}$; and $\mathcal F$ is analytically $X$-flat at $y$, tested after every good analytic base change over every complete valued extension of $K$.
\end{theorem}

\begin{theorem}[The general graded finite-map criterion]
\label{fnd:generalgradedfinitecriterion}
A bounded homomorphism $A\to B$ of generalized affinoid
algebras is finite and admissible if and only if
\[
 \widetilde A^{\rm gr}\longrightarrow\widetilde B^{\rm gr}
\]
is finite. In particular $\widetilde A^{\rm gr}$ is a
finitely generated graded $\widetilde K^{\rm gr}$-algebra.
\end{theorem}

proof.tex:
\begin{proof}
For the forward implication, apply the
\hyperref[fnd:nag001886:good-affine-forward]{affinoid-neighbourhood criterion}
to the given germ over its complete field. For the reverse implication,
apply the \hyperref[fnd:nag001982:affine-to-good]{affine-to-good clause}
to the same germ and its affine graded birational reduction.
\end{proof}

statement.tex:
\begin{theorem}[Goodness is detected by graded reduction]
\label{fnd:goodgermiffaffinereduction}
An analytic germ over an arbitrary complete non-Archimedean
field is good if and only if its graded birational reduction
is affine.
\end{theorem}

\begin{theorem}[An \'etale-domain factorization in rank zero]
\label{fnd:rankzeroetaledomainfactorization}
Let $f:Y\to X$ be a morphism of good analytic spaces, quasi-smooth of differential rank zero at $y$, and put $x=f(y)$. There are an ordinary affinoid neighborhood $U$ of $x$, a finite \'etale morphism $T\to U$, and an ordinary affinoid neighborhood $V$ of $y$ such that $f|_V$ factors as an affinoid-domain inclusion $V\hookrightarrow T$ followed by $T\to U\hookrightarrow X$.
\end{theorem}

\begin{theorem}[Smooth envelopes of good quasi-smooth germs]
\label{fnd:quasismoothsmoothenvelope}
Let $f:Y\to X$ be a morphism of good analytic spaces over any complete field. It is quasi-smooth at $y$ if and only if an ordinary affinoid neighborhood $V$ of $y$ is, over an ordinary neighborhood of $x=f(y)$, an affinoid domain of a smooth analytic $X$-space. If the differential rank at $y$ is $d$, the smooth ambient space may be chosen of relative dimension $d$.
\end{theorem}

\begin{theorem}[Minimal-interface scalar assembly; F8SA-S]\label{thm:scalar}
Assume S1--S3, the frozen interfaces above, R-S1 and R-F7. If the exact
interfaces IP, IL and IH hold on the data just specified, then
for every ordinary \((n-1,n-1)\)-test supported in \(C\),
\begin{equation}\label{eq:scalarPL}
                         L_f(\dd\eta)=\int_D\eta.
\end{equation}
The right side is the frozen integral with the full actual quotient
structure of \(D\). This is a conditional scalar equality. It neither
verifies IP/IL/IH nor admits a general current-level PL statement.
\end{theorem}

\begin{proposition}[Native measure decomposition and total variation; F8CR-V]
\label{prop:variation}
For the data of \eqref{eq:components} and a compact ordinary top form
\(\omega\), write \(\omega_i=i_i^*\omega\). Then
\begin{align}
 \mu_{X,\omega}&=\sum_i m_i(i_i)_*\mu_{X_i,\omega_i},
                                      \label{eq:measure-split}\\
 |\mu_{X,\omega}|&\leq\sum_i m_i(i_i)_*|\mu_{X_i,\omega_i}|.
                                      \label{eq:variation}
\end{align}
For each closed embedding separately,
\( |(i_i)_*\nu|=(i_i)_*|\nu|\). In general no equality of the total
variation of the sum is asserted.
\end{proposition}

\begin{proposition}[Absolute logarithmic integrability and native normalization; F8CR-I]
\label{fnd:nag002976:fixed-test-native-log}
Let \(f\in A\) be regular and let \(\beta\) be any compact ordinary
\((n,n)\)-form on \(X\). Put \(\beta_i=i_i^*\beta\) and extend
\(\log|f|\) by zero on \(D\). This extension is Borel, is integrable
against \(|\mu_{X,\beta}|\), and satisfies
\begin{align}
 \int_X|\log|f||\,d|\mu_{X,\beta}|
 &\leq\sum_i m_i M_i\,|\mu_{X_i,\beta_i}|(X_i)<\infty,
                                                    \label{eq:logbound}\\
 L_f(\beta)=\int_X\log|f|\,d\mu_{X,\beta}
 &=\sum_i m_i L_{f_i}(\beta_i).             \label{eq:logsplit}
\end{align}
Here \(M_i\) is any bound for \(|\log|f_i||\) on
\(\Supp\beta_i\), and is zero for an empty support. The measure
assigns zero variation mass to \(D\), so its assigned logarithm
value there is immaterial. No scalar PL or ZP hypothesis is needed.
\end{proposition}

\begin{lemma}[Smooth scalar integration by parts; F8MG-S]
\label{fnd:nag002995:smooth-pairing}
For ordinary smooth \(h\) on a neighbourhood of the compact support
of \(\eta\in\A^{n-1,n-1}_{U,c}\),
\begin{equation}\label{fnd:nag002995:pairing-equation}
                    \int_U h\,\dd\eta=\int_U\dd h\wedge\eta.
\end{equation}
The compact support in \(U\subseteq\Int(X/K)\) is retained.
\end{lemma}

\begin{lemma}[Compact faithfulness and ordinary presentation]\label{fnd:nag003074:compact-faithfulness}
Let $C\subset X^\an$ be affinoid, let $f$ be a finite analytic unit tuple on $C$, and let $\alpha$ be a smooth ambient superform near $s_f(C)$. Then
\begin{equation}\label{fnd:nag003074:compact-kernel}
 s_f^*\alpha=0\text{ in the CLD G-sheaf on }C
       \quad\Longleftrightarrow\quad \alpha|_{s_f(C)}=0.
\end{equation}
Every germ of $\A_{\rm CLD}$ has a presentation by a finite analytic unit tuple on an ordinary open neighborhood and an ambient smooth superform. Consequently \eqref{fnd:nag003074:reflection-map} defines an isomorphism of ordinary sheaves
\[
                           c:\A_{\rm mom}\xrightarrow{\sim}\A_{\rm CLD}.
\]
\end{lemma}

\begin{theorem}[Norm replacement gives the ordinary algebraic sheaf]\label{thm:ordinary}
There is a canonical isomorphism of ordinary sheaves of bigraded differential real algebras
\begin{equation}\label{eq:iso}
 \A_{\rm CLD}\xleftarrow[\sim]{\ c\ }\A_{\rm mom}
                  \xrightarrow[\sim]{\ \Phi\ }\A_{\rm alg}.
\end{equation}
On a moment representative, $\Phi$ is obtained by the single simultaneous replacement \eqref{eq:norm} and pullback along the integral affine character map of Proposition~\ref{prop:intrinsic}. It is independent of the replacement, the compact witness, the chosen algebraic chart, and the lifts of a unit-lattice basis. The maps commute with ordinary restriction and with algebraic pullbacks. They preserve ordinary supports exactly.
\end{theorem}

proof.tex:
\begin{proof}
The original universal kernel tests every compatible algebraic morphism and chart. The \mbox{\hyperref[lem:gk]{identity test}} detects all-face tangential vanishing: the chart has its actual canonical support, finite pure structure and strictly positive top weights, so a nonzero tangential coefficient on a maximal cell would have a nonzero local pairing. Continuity gives vanishing on its faces. Conversely, the \mbox{\hyperref[lem:gk]{compatible-chart test}} pulls back tangential vanishing along the induced integral affine map on each actual compatible chart, after a refinement carrying each source cell into a target cell. This gives zero in every test kernel with the stated actual supports and weights.

Thus the smooth chart quotient is exactly the quotient used for $\A_{\rm alg}$. Proposition~\ref{prop:intrinsic} supplies a cofinal system of local intrinsic refinements at each point. A zero germ in GK is witnessed, after ordinary sheafification and the filtered chart colimit, by a smaller ordinary neighbourhood with a compatible chart where its smooth representative belongs to the universal kernel. Pass to a common intrinsic refinement inside this neighbourhood and inside the original chart. The preceding kernel equality makes it zero in $\A_{\rm alg}$. This proves injectivity on stalks. Every locally smooth representative lies in the image by construction. This proves the displayed isomorphism and its asserted image, rather than inferring injectivity from the mere existence of a map. Naturality follows from the \mbox{\hyperref[prop:torus]{actual character pullback}} on compatible source charts. Wedges and $d',d''$ descend from the identical ambient operations on the all-face quotient by \mbox{\hyperref[v037:forms:finitecoverfaithfulness]{tangential preservation}}.
\end{proof}

statement.tex:
\begin{proposition}[Map to the original universal quotient]\label{prop:gk}
Under these target-object hypotheses, the chartwise map $\alpha\mapsto[\alpha]$ induces a canonical isomorphism
\[
 \A_{\rm alg}\xrightarrow{\sim}\mathcal B_{\rm GK,sm}
                     \hookrightarrow\mathcal B_{\rm GK}.
\]
Together with \eqref{eq:iso}, this is an actual comparison of the current CLD ordinary smooth sheaf and the smooth image in the original GK construction on the stated common category. It commutes with algebraic pullback and the given GK smooth differential operations.
\end{proposition}

\begin{proposition}[Weighted meromorphic comparison; F8NM-Q]\label{fnd:nag003100:weighted-meromorphic}
On a pure affinoid \(V\), let \(f=a/b\) with \(a,b\) ambient regular,
and retain the reviewed pure-zero-space premises on actual refinements.
Writing \(f_i=a_i/b_i\), one has
\begin{align}
 L_f(\alpha)&=\sum_i m_i L_{f_i}(j_i^*\alpha),\label{eq:nag003100:logsplit}\\
 \divis_V(f)&=\sum_i m_i(j_i)_*\divis_{V_i}(f_i),\label{eq:nag003100:cycles}
\end{align}
for ordinary compact top tests \(\alpha\). The second identity includes
the actual analytic Cartier coefficients and their native compact-test
pairings. Local regular quotient atlases glue both sides independently
of their presentations. No ambient \(S_1\) is needed.
\end{proposition}

\begin{theorem}[Non-\(S_1\) fixed-test identities; F8NM-G]\label{thm:fixed}
Under the exact reviewed component/scalar and ZP inputs above, every
ambient regular meromorphic \(f\) on \(U\) satisfies
\begin{equation}\label{eq:meromorphic}
 L_f(\dd\eta)=\delta_{\divis(f)}(\eta)
 \qquad(\eta\in\A_c^{n-1,n-1}(U)).
\end{equation}
Let \(\overline{\cL}\) have ordinary smooth metric weights and a given
ambient regular meromorphic section \(s\). Its potential pairing
\(G_s\), full Cartier divisor \(D_s\), and ordinary curvature satisfy
\begin{equation}\label{eq:metric}
 G_s(\dd\eta)+\delta_{D_s}(\eta)
       =\int_U c_1(\overline{\cL})\wedge\eta.
\end{equation}
These are fixed-test statements before any topology is invoked.
\end{theorem}

\begin{theorem}[Continuous multiplication of a starting structure current]\label{f9si:mult}
Let $Y$ be good, Hausdorff, and pure of analytic dimension $d\geq1$. For every real continuous $u$ on $Y$, define
\begin{equation}\label{eq:Ju}
 J_u(\alpha)=\int_Y u\,d\mu_{Y,\alpha},\qquad
 \alpha\in\E^{d,d}(Y),
\end{equation}
where $\mu_{Y,\alpha}$ is the exact frozen native top-form measure of \NAG{002970}. Then $J_u$ is an actual native current. On each cutoff stage there is a constant $A_i\geq0$, independent of $u$ and $\eta$, such that
\begin{align}
 |\mu_{Y,Q_i\eta}|(Y)&\leq A_i p_{t_f(V),0}(\eta),\label{eq:variationbound}\\
 |J_u(Q_i\eta)|&\leq A_i\sup_{C_i}|u|\,p_{t_f(V),0}(\eta).\label{eq:multbound}
\end{align}
For an empty support the expressions are zero. The construction is linear in $u$ and in the test, local on ordinary opens, and agrees with $\int_Yu\alpha$ when $u$ is ordinary smooth. If $u_a\to u$ uniformly on every compact set, then $J_{u_a}\to J_u$ on all tests, uniformly on each fixed stage with bounded indicated order-zero seminorm.

For the affinoid data of Theorem~\ref{f9si:cycle},
\begin{equation}\label{eq:multcomponents}
 J_u^X=\sum_i m_i(j_i)_*J_{u|_{X_i}}^{X_i}.
\end{equation}
The same construction component by component supplies a continuous multiplier on every supplied weighted analytic cycle of that theorem.
\end{theorem}

proof.tex:
\begin{proof}
Theorem~\ref{f9si:mult} gives $J_{u_a}$ on the pure open subspace $U_a$. The native differential check in Theorem~\ref{f9cp:operators} gives continuous $\DD$ on tests. In an ordinary stage it raises coefficient order by at most two; the factorization of cutoff stages in \NAG{002473} gives the same finite-stage continuity. Thus
$(\DD J_{u_a})(\alpha)=J_{u_a}(\DD\alpha)$ is a current. The ordinary differential identities of \NAG{002424} imply that it is closed. There is no positivity inference in this step.

We check frame changes by the exact frozen Stokes theorem, rather than by a pending frame-quotient result. Let $h$ be an ordinary smooth scalar on an overlap and $\alpha\in\E^{n-1,n-1}$ have support there. Each of $h\,d''\alpha$ and $d'h\wedge\alpha$ has compact support in that overlap, hence in $\Int(X/K)$ after zero extension. By \NAG{002577},
\begin{align*}
 0&=\int_X d'h\wedge d''\alpha+\int_X h\DD\alpha,\\
 0&=-\int_X\DD h\wedge\alpha-\int_X d'h\wedge d''\alpha.
\end{align*}
Their sum proves
\begin{equation}\label{eq:parts}
 \int_X h\DD\alpha=\int_X(\DD h)\wedge\alpha.
\end{equation}
Here the first differentiated test has bidegree $(n-1,n)$, the second $(n,n-1)$, and the second displayed minus sign uses the total degree one of $d'h$ and $d''d'=-d'd''$. There is no residual $(-1)^n$ factor.

If $e_a=g_{ab}e_b$, then $u_a=u_b-\log|g_{ab}|$. A unit logarithm is ordinary smooth: in its own moment coordinate it has affine representative $-x$, so \NAG{002424} gives $\DD\log|g_{ab}|=0$. Theorem~\ref{f9si:mult} for smooth multipliers and \eqref{eq:parts} show that $\DD J_{u_a}=\DD J_{u_b}$ on every overlap test. In particular, the distributional frame identity is proved here for this starting current, without assuming a Chern product exists.

For completeness, glue these particular currents on a test $\alpha$ by a finite partition $\chi_a$ equal to one near $\supp\alpha$, supplied by \NAG{002428}, and set $C(\alpha)=\sum_a C_a(\chi_a\alpha)$. Multiplying two such partitions reduces independence to the overlap equality. For one cutoff stage the support is fixed, so choose its cover and partition once. Multiplication by each fixed $\chi_a$ maps that stage continuously to a fixed ordinary stage: adjoin the finitely many moments presenting $\chi_a$ and use the coefficient product rule. The constants and moments are fixed before the variable input. Thus the finite sum is continuous by \NAG{002473}, and it has the stated restrictions. Differentiation commutes with restrictions; since every local $C_a$ is closed, its derivative vanishes on each cover member and therefore on a partition of any compact test. This proves global closedness.

Additivity and root scaling follow from $u_{L\otimes M}=u_L+u_M$, $u_{L^{\otimes e}}=e u_L$, and linearity of $J$ and $\DD$. No root is taken in $K$, and the absolute value is not renormalized. Formula~\eqref{eq:parts} proves the smooth-potential identification. Applying the same proof on each pure analytic component and then using commuting pullback and differentiation from Theorem~\ref{f9si:cycle} and the \hyperref[fnd:nag003106:closed-pullback]{closed-pullback clause} proves the cycle assertion with exactly its given coefficients.
\end{proof}

statement.tex:
\begin{theorem}[The first continuous-metric Chern current]\label{f9si:chern}
Let $X$ be good, Hausdorff, and pure of analytic dimension $n\geq1$, and let $U\subseteq\Int(X/K)$ be ordinary open. Let $L$ be an analytic line bundle on $U$ with a supplied continuous metric. In a local frame $e_a$, put $u_a=-\log\|e_a\|$. The local currents
\begin{equation}\label{eq:chern}
 C(L,\|\cdot\|)|_{U_a}=\DD J_{u_a}
 \quad\text{of bidimension }(n-1,n-1)
\end{equation}
glue to a closed native current independent of frames, evaluated on every ordinary compact test in that bidegree. They are additive in tensor products. If a metric on $L^{\otimes e}$ is given and its positive real $e$-th root is used on $L$, the resulting current is $1/e$ of the current of the power metric. For a smooth potential it equals the current $\alpha\mapsto\int_U(\DD u_a)\wedge\alpha$ locally.

The same assertion holds against a supplied weighted analytic cycle in Theorem~\ref{f9si:cycle}, with $n$ replaced by its component dimension and its weights retained. No positivity, order-zero property of $C(L,\|\cdot\|)$, or second continuous multiplication is claimed.
\end{theorem}

\begin{theorem}[First curvature and its supported signed test measures]\label{f9tf:first}
For $u\in\PP(U)$ define on every $\alpha\in\E^{n-1,n-1}(U)$
\begin{equation}\label{eq:first}
 T_u(\alpha)=\int_U u\,d\mu_{U,\DD\alpha},
\end{equation}
using the frozen top-form measure of \NAG{002970}. This is a closed native current of bidimension $(n-1,n-1)$. It has the canonical signed measures $\nu_{u,\alpha}:=\nu_{T_u,\alpha}$ of Theorem~\ref{f9tf:measure}, and all continuous multipliers on it exist with the proved fixed-stage bounds. If $u$ is a convex piece of \eqref{eq:decomp}, $T_u$ is nonnegative on every test nonnegative on $(n-1)$-planes; for general $u$ it is locally a fixed finite signed sum of such currents.

On a local presentation consisting only of finite affine maxima, let $Z_u$ be the union of the inverse images of their non-affine loci in the ambient moment spaces. Then
\begin{equation}\label{eq:support}
 \supp T_u\subseteq Z_u,\qquad
 \supp\nu_{u,\alpha}\subseteq Z_u\cap\supp\alpha.
\end{equation}
No positivity is asserted for an arbitrary signed or model potential. For a pure affinoid $Y=\mathcal M(A)$ with reduced components $j_i:Y_i\hookrightarrow Y$ and $m_i=\operatorname{length}_{A_{\mathfrak q_i}}A_{\mathfrak q_i}$, on interior tests one has
\begin{equation}\label{eq:nag003179:components}
 T_u=\sum_i m_i(j_i)_*T_{u|Y_i},\qquad
 \nu_{u,\alpha}=\sum_i m_i(j_i)_*\nu_{u|Y_i,j_i^*\alpha}.
\end{equation}
Thus the full generic nilpotent lengths, not merely the reduced components, remain in the scalar measures.
\end{theorem}

