\begin{theorem}[Variation control and convergence against continuous multipliers]\label{f9tf:convergence}
Work on a fixed local decomposition \eqref{eq:decomp}. For every fixed compact test $\beta\in\E^{n-1,n-1}(U)$, the measures $\nu_{u_\epsilon,\beta}$ have common compact support in $\supp\beta$, uniformly bounded total variation for $0<\epsilon\leq1$, and converge to $\nu_{u,\beta}$ against every continuous scalar on that compact set. On each fixed cutoff stage the variation bound is uniform in $\epsilon$ with coefficient order zero.

More explicitly, for a stage domination form $\theta_i$ of Theorem~\ref{f9tf:measure}, one may take
\begin{equation}\label{eq:uniformmass}
 A_{u,i}=c_i\sum_a|q_a|
 \left(T_{w_a}(\theta_i)+\log m_a\,|\mu_{U,\DD\theta_i}|(U)\right),
\end{equation}
with $\log m_a=0$ for an unchanged smooth convex piece. Then
$|\nu_{u_\epsilon,Q_i\eta}|(U)\leq A_{u,i}p_{t_f(V),0}(\eta)$.
For an arbitrary fixed $\beta$, a finite decomposition into cutoff images gives a bound $M_{u,\beta}$ for these variations and the variation of $\nu_{u,\beta}$.

If $v_\epsilon\to v$ uniformly on $\supp\beta$, then
\begin{equation}\label{eq:joint}
 \int v_\epsilon\,d\nu_{u_\epsilon,\beta}
 \longrightarrow\int v\,d\nu_{u,\beta}.
\end{equation}
The result also holds for an ordinary smooth $v$ left unchanged. It is proved for this fixed positive decomposition and its explicit approximants; mere weak convergence of arbitrary signed currents is not substituted for these hypotheses.
\end{theorem}

\begin{theorem}[All-test interchange of two declared potentials]\label{f9tf:two}
For $u,v\in\PP(U)$ define
\begin{equation}\label{eq:two}
 R(u,v)=\DD(vT_u),\qquad
 R(u,v)(\alpha)=\int v\,d\nu_{u,\DD\alpha}
 \quad(\alpha\in\E^{n-2,n-2}(U)).
\end{equation}
This is a closed native current of bidimension $(n-2,n-2)$ and
\begin{equation}\label{eq:interchange}
 R(u,v)=R(v,u)
 \quad\text{on every indicated compact native test}.
\end{equation}
It is bilinear, local, and independent of all decompositions and approximations used in the proof. It is nonnegative on $(n-2)$-plane nonnegative tests for two convex pieces, and locally a finite signed sum of such currents in general. Its support lies in $\supp T_u\cap\supp T_v$; for two finite-max presentations it lies in $Z_u\cap Z_v$. For the affinoid component data of \eqref{eq:nag003179:components}, it also satisfies
\[
 R(u,v)=\sum_i m_i(j_i)_*R(u|Y_i,v|Y_i)
\]
on interior tests, with the same original lengths.

Local potentials in $\PP$ of two actual continuously metrized analytic lines therefore give a frame-independent symmetric two-factor current. Replacing power metrics by positive real roots of exponents $e_1,e_2$ scales it by $1/(e_1e_2)$. No equality with an atomic model measure, divisor-current formula, or general height is asserted.
\end{theorem}

\begin{theorem}[A verifiable model class and coordinate calibration]\label{f9tf:model}
Suppose a model line $\mathcal A$ is supplied with a finite family of global sections generating it as an invertible sheaf. Its actual bounded-frame norm has, in every ordinary analytic local frame, a potential locally equal to a maximum of finitely many logarithms of analytic units. In particular it is continuous and belongs to $\PP$.

Consequently, for $i=1,2$, suppose a root model presentation of $L_i$ of exponent $e_i\geq1$ is supplied with an actual model isomorphism
\begin{equation}\label{eq:modelquotient}
 \mathcal M_i\simeq\mathcal A_i\otimes\mathcal B_i^{-1},
\end{equation}
where both $\mathcal A_i$ and $\mathcal B_i$ have supplied finite generating sections. Then its metric satisfies the hypotheses of Theorems~\ref{f9tf:first}--\ref{f9tf:two}, on all native tests. The statement does not require a reduced special fibre or assert positivity of the quotient metric. A local variant requires the resulting norm identities on ordinary analytic neighborhoods; generation on a list of formal domains alone is not claimed sufficient.

For a normalization example in every $n\geq2$, restrict the standard model metrics from $(\mathbf P_R^1)^n$ to the generic torus, and write $t_k=-\log|z_k|$ and
$w_i=\max(0,t_i)$. These are the potentials of the model frames $X_{1,i}$. If $i\ne j$, and $\psi\in C_c^\infty(\R^n)$, put
\[
 \alpha= t^*\!\left(\psi\bigwedge_{k\ne i,j}(d't_k\wedge d''t_k)\right).
\]
Then
\begin{equation}\label{eq:coordinate}
 R(w_i,w_j)(\alpha)=
 \int_{\R^{n-2}}\psi(t_1,\ldots,t_n)\big|_{t_i=t_j=0}
                         \prod_{k\ne i,j}dt_k.
\end{equation}
For $i=j$, $R(w_i,w_i)=0$ on all native tests. Root metrics divide \eqref{eq:coordinate} by $e_i e_j$.
The dual model metric with potential $-w_i$ is not positive: for a nonnegative coordinate test
$\beta=t^*(\psi\bigwedge_{k\ne i}d't_k\wedge d''t_k)$ with
$\int\psi|_{t_i=0}\prod_{k\ne i}dt_k=1$, one has $T_{-w_i}(\beta)=-1$.
\end{theorem}

